#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Run from the repo root wherever the script is launched from.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ENV_FILE="backend/.env"   # values below are read from / written to the backend env

MIGRATION_1="backend/prisma/manual-migrations/20261123_add_morning_digest.sql"
MIGRATION_2="backend/prisma/manual-migrations/20261124_add_analytics_opt_out.sql"
RUN_DATE="$(date -u +%Y-%m-%d)"
RUN_FILE="docs/test-runs/RUN_${RUN_DATE}.md"

# copy_file_to_clipboard FILE: best effort; returns non-zero if no clipboard tool.
copy_file_to_clipboard() {
  if   command -v pbcopy   >/dev/null 2>&1; then pbcopy   < "$1"
  elif command -v wl-copy  >/dev/null 2>&1; then wl-copy  < "$1"
  elif command -v xclip    >/dev/null 2>&1; then xclip -selection clipboard < "$1"
  elif command -v clip.exe >/dev/null 2>&1; then clip.exe < "$1"
  else return 1; fi
}

# run_sql FILE "label": run via psql on DIRECT_URL after confirmation, or walk
# the human through the Supabase SQL editor. Both migrations are idempotent.
run_sql() {
  local file="$1" label="$2"
  say "File: $file"
  if [[ -n "${DIRECT_URL:-}" ]] && command -v psql >/dev/null 2>&1; then
    if confirm "Run $label now with psql against DIRECT_URL?"; then
      psql "$DIRECT_URL" -v ON_ERROR_STOP=1 -q -f "$file"
      printf '  %s✓ applied%s %s\n' "$GREEN" "$RESET" "$label"
      return
    fi
    note "Skipped psql; falling back to the SQL editor."
  fi
  open_url "$SQL_EDITOR_URL"
  if copy_file_to_clipboard "$file"; then
    step "The SQL is on your clipboard. Paste it into a new query and click Run."
  else
    step "Open $file, copy its whole contents, paste into a new query and click Run."
  fi
  step "It should finish with 'Success. No rows returned'."
  pause "Press Enter once it has run successfully"
}

banner "Oshi first deploy — PR #3 cutover"

# ── Stage 1 ────────────────────────────────────────────────────────────────
stage "Preflight: Supabase project"
say "This wizard applies the PR #3 database migrations, sets the backend's"
say "PostHog key, walks the deploy, and records a P0 test run."
if [[ ! -f "$ENV_FILE" ]]; then
  warn "No $ENV_FILE found. Run this on the machine where the backend's .env lives,"
  warn "or let this wizard create one with just the values it needs."
fi
ask SUPABASE_URL "Supabase project URL (https://<ref>.supabase.co):"
write_env SUPABASE_URL "$SUPABASE_URL"
PROJECT_REF="${SUPABASE_URL#https://}"; PROJECT_REF="${PROJECT_REF%%.*}"
SQL_EDITOR_URL="https://supabase.com/dashboard/project/${PROJECT_REF}/sql/new"
DIRECT_URL="$(_existing DIRECT_URL || true)"
if [[ -n "$DIRECT_URL" ]] && command -v psql >/dev/null 2>&1; then
  say "Found DIRECT_URL in $ENV_FILE and psql on PATH: I can run the SQL for you."
else
  note "No DIRECT_URL/psql pair, so you'll paste SQL into the Supabase SQL editor."
fi
pause

# ── Stage 2 ────────────────────────────────────────────────────────────────
stage "Migration 1: Morning Digest column"
say "Adds users.morning_digest and allows 'morning_digest' notification logs."
warn "Must run BEFORE the backend deploys: until it exists, every users query fails."
run_sql "$MIGRATION_1" "migration 1 (morning_digest)"

# ── Stage 3 ────────────────────────────────────────────────────────────────
stage "Migration 2: analytics opt-out column"
say "Adds users.analytics_opt_out so server-side analytics respect the app toggle."
warn "Same rule: run BEFORE the backend deploys."
run_sql "$MIGRATION_2" "migration 2 (analytics_opt_out)"

# ── Stage 4 ────────────────────────────────────────────────────────────────
stage "Verify both columns exist"
VERIFY_SQL="SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name='users' AND column_name IN ('morning_digest','analytics_opt_out') ORDER BY 1;"
if [[ -n "$DIRECT_URL" ]] && command -v psql >/dev/null 2>&1; then
  found="$(psql "$DIRECT_URL" -Atq -c "$VERIFY_SQL" | tr '\n' ' ')"
  say "Columns found: ${found:-none}"
  if [[ "$found" != *analytics_opt_out* || "$found" != *morning_digest* ]]; then
    warn "Both columns must exist before you deploy. Re-run stages 2–3."
    pause "Press Enter to continue anyway (or Ctrl-C to stop)"
  else
    printf '  %s✓ both columns present%s\n' "$GREEN" "$RESET"
  fi
else
  open_url "$SQL_EDITOR_URL"
  step "Run this query; it must return two rows (analytics_opt_out, morning_digest):"
  note "$VERIFY_SQL"
  pause "Press Enter once you see both rows"
fi

# ── Stage 5 ────────────────────────────────────────────────────────────────
stage "Optional: category backfill for existing dev accounts"
say "Accounts created before 2026-11-23 stored 10 of their default categories as"
say "custom, so the free plan's 3-custom-category limit blocks them."
note "Caveat: it also marks any custom category named like a default as a default."
note "Skip this for a brand-new database; it changes data and has no undo."
if confirm "Backfill is_system_default on existing default categories?"; then
  BACKFILL_SQL="UPDATE categories SET is_system_default = true WHERE name IN ('Learning','Business','Travel','Food','Fitness','Entertainment','Shopping','Inspiration','Tech','People','Other','Finance','Technology','Culture','News','Personal');"
  if [[ -n "$DIRECT_URL" ]] && command -v psql >/dev/null 2>&1; then
    psql "$DIRECT_URL" -v ON_ERROR_STOP=1 -c "$BACKFILL_SQL"
  else
    open_url "$SQL_EDITOR_URL"
    step "Run this statement:"
    note "$BACKFILL_SQL"
    pause "Press Enter once it has run"
  fi
else
  note "Skipped."
fi

# ── Stage 6 ────────────────────────────────────────────────────────────────
stage "PostHog key for server-side analytics"
say "The backend reports to the same PostHog project as the app."
APP_KEY="$(ENV_FILE=app/.env _existing EXPO_PUBLIC_POSTHOG_API_KEY || true)"
if [[ -n "$APP_KEY" ]] && confirm "Reuse the app's EXPO_PUBLIC_POSTHOG_API_KEY from app/.env?"; then
  POSTHOG_API_KEY="$APP_KEY"
else
  open_url "https://app.posthog.com/project/settings"
  step "In PostHog project settings, copy the Project API key (starts phc_)."
  ask_secret POSTHOG_API_KEY "Paste the project API key (Enter to skip analytics):"
fi
if [[ -n "${POSTHOG_API_KEY:-}" ]]; then
  write_env POSTHOG_API_KEY "$POSTHOG_API_KEY"
  if command -v railway >/dev/null 2>&1 && confirm "Set POSTHOG_API_KEY on Railway via the railway CLI (linked project)?"; then
    railway variables --set "POSTHOG_API_KEY=$POSTHOG_API_KEY"
  else
    open_url "https://railway.com/dashboard"
    step "Open the Oshi backend service → Variables → add POSTHOG_API_KEY with that value."
    pause "Press Enter once it's saved"
  fi
else
  SKIPPED+=("POSTHOG_API_KEY not set: server-side analytics stay off (safe)")
fi

# ── Stage 7 ────────────────────────────────────────────────────────────────
stage "Deploy the backend"
say "Railway auto-deploys from main. Merge PR #3 (or deploy the branch) now."
open_url "https://github.com/murtazatiz/Oshi/pull/3"
step "Merge the PR once you're happy with it; Railway starts a deploy."
step "In the deploy's build logs, check the Node version is 20.20+ or 22.22+."
note "backend/package.json engines asks for ^20.20.0 || >=22.22.0 (posthog-node needs it)."
pause "Press Enter when the deploy is live"
ask API_HEALTH_URL "Backend health URL (e.g. https://api.oshi.app/health):"
if command -v curl >/dev/null 2>&1; then
  if curl -fsS --max-time 10 "$API_HEALTH_URL" >/dev/null; then
    printf '  %s✓ health check passed%s\n' "$GREEN" "$RESET"
  else
    warn "Health check failed. Check the Railway deploy logs before testing devices."
    pause "Press Enter to continue"
  fi
fi

# ── Stage 8 ────────────────────────────────────────────────────────────────
stage "P0 device test run"
say "Walks every P0 case in docs/TEST_CASES.md and records results to $RUN_FILE."
note "Use a dev/staging build pointed at the backend you just deployed."
if ! confirm "Start the P0 run now?"; then
  SKIPPED+=("P0 device run: re-run this wizard and choose it at stage 8")
  finish; return
fi
mkdir -p docs/test-runs
{
  printf '# Test run — %s (P0)\n\n' "$RUN_DATE"
  printf '| ID | Result | Notes |\n|----|--------|-------|\n'
} > "$RUN_FILE"
P0_ROWS=()   # bash 3.2-safe (macOS): no mapfile
while IFS= read -r line; do P0_ROWS+=("$line"); done \
  < <(grep -E '^\| TC-[A-Z]+-[0-9]+ \| P0 \|' docs/TEST_CASES.md)
total=${#P0_ROWS[@]}; i=0; passed=0; failed=0
for row in "${P0_ROWS[@]}"; do
  i=$((i + 1))
  IFS=$'\t' read -r tc_id tc_case tc_steps tc_expected < <(
    printf '%s\n' "$row" | awk -F' \\| ' '{ sub(/^\| /, "", $1); print $1 "\t" $4 "\t" $5 "\t" $6 }')
  _clear
  printf '\n%s%s▸ P0 case %s/%s · %s — %s%s\n\n' "$BOLD" "$BLUE" "$i" "$total" "$tc_id" "$tc_case" "$RESET"
  printf '  %sSteps:%s %s\n\n' "$BOLD" "$RESET" "$tc_steps"
  printf '  %sExpected:%s %s\n\n' "$BOLD" "$RESET" "${tc_expected% |}"
  result=""
  while [[ ! "$result" =~ ^[pfs]$ ]]; do
    printf '  %s? Result: (p)ass, (f)ail, (s)kip %s' "$YELLOW" "$RESET"
    read -r result || result="s"
  done
  case "$result" in
    p) mark="✅"; passed=$((passed + 1)) ;;
    f) mark="❌"; failed=$((failed + 1)) ;;
    s) mark="⏭" ;;
  esac
  printf '  %sNotes (optional):%s ' "$DIM" "$RESET"
  read -r notes || notes=""
  printf '| %s | %s | %s |\n' "$tc_id" "$mark" "${notes//|/\/}" >> "$RUN_FILE"
done
printf '\n%s passed · %s failed · %s skipped of %s P0 cases.\n' \
  "$passed" "$failed" "$((total - passed - failed))" "$total" >> "$RUN_FILE"
printf '  %s✓ recorded%s %s (%s passed, %s failed)\n' "$GREEN" "$RESET" "$RUN_FILE" "$passed" "$failed"
(( failed > 0 )) && SKIPPED+=("$failed P0 failure(s): log each in docs/FIXES_LOG.md and fix before release")
pause

finish
}

run_wizard "$@"; exit
